//! ASS export — port of `src/util/parse/additional/file/danmaku_ass.py`:
//! the native layout engine (scroll/top/bottom tracks) plus the style
//! header. Every Danmaku Style option is honored (font name/size/bold/
//! italic/underline/strike, border/shadow, display_area, opacity,
//! scroll/static duration, minimum_gap, resolution).

use crate::style::DanmakuStyle;
use crate::DanmakuEntry;

const ASS_BASE: &str = "[Script Info]
; Script generated by Bili23 Downloader
; http://bili23.scott-sloan.cn
Title: {title}
ScriptType: v4.00+
WrapStyle: 2
Collisions: Normal
ScaledBorderAndShadow: yes
Aspect Ratio: {width}:{height}
YCbCr Matrix: TV.601
PlayResX: {width}
PlayResY: {height}

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
{style}

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
{dialogues}
";

/// Render the full ASS document.
pub fn render_ass(entries: &[DanmakuEntry], title: &str, style: &DanmakuStyle) -> String {
    let (style_str, screen_width, screen_height) = style_info(style);
    let mut engine = LayoutEngine::new(style, screen_width, screen_height);
    let dialogues = convert_dialogues(&mut engine, entries, style);

    ASS_BASE
        .replace("{title}", title)
        .replace("{style}", &style_str)
        .replace("{dialogues}", &dialogues.join("\n"))
        .replace("{width}", &screen_width.to_string())
        .replace("{height}", &screen_height.to_string())
}

fn style_info(style: &DanmakuStyle) -> (String, i32, i32) {
    let w = style.resolution.width;
    let h = style.resolution.height;
    let alpha = ((1.0 - style.advanced.opacity as f64 / 100.0) * 255.0) as i32;
    let alpha_hex = format!("{alpha:02X}");

    // Mirrors Python's format string exactly, including the int() casts of
    // the booleans and str() of the border float.
    let style_str = format!(
        "Style: Default,{font},{size},&H{alpha}FFFFFF,&H{alpha}0000FF,&H{alpha}000000,&H{alpha}000000,{bold},{italic},{underline},{strikeout},100,100,0,0,1,{border},{shadow},7,0,0,0,1",
        font = style.font.name,
        size = style.font.size,
        alpha = alpha_hex,
        bold = style.font.bold as i32,
        italic = style.font.italic as i32,
        underline = style.font.underline as i32,
        strikeout = style.font.strike as i32,
        border = fmt_float(style.border.border),
        shadow = style.border.shadow,
    );
    (style_str, w, h)
}

/// Python `str(float)`: shortest round-trip repr, integral values keep
/// the trailing `.0` (e.g. `1.0`, not `1`).
fn fmt_float(v: f64) -> String {
    if v == v.trunc() && v.is_finite() {
        format!("{v:.1}")
    } else {
        format!("{v}")
    }
}

/// Python `Time.format_ass_time_by_ms` verbatim (centis clamps at 99).
fn ass_time(ms: i64) -> String {
    let hours = ms / 3_600_000;
    let minutes = (ms % 3_600_000) / 60_000;
    let seconds = (ms % 60_000) / 1000;
    let mut centis = ((ms % 1000) as f64 / 10.0).round() as i64;
    if centis == 100 {
        centis = 99;
    }
    format!("{hours}:{minutes:02}:{seconds:02}.{centis:02}")
}

/// A scrolling-danmaku track (Python `ScrollTrack`).
struct ScrollTrack {
    screen_width: i32,
    min_gap: i32,
    last_stime: Option<i64>,
    last_duration: i64,
    last_width: i32,
    last_speed: f64,
}

impl ScrollTrack {
    fn new(screen_width: i32, min_gap: i32) -> Self {
        Self {
            screen_width,
            min_gap,
            last_stime: None,
            last_duration: 0,
            last_width: 0,
            last_speed: 0.0,
        }
    }

    /// Python `can_fit`: the previous tail must have cleared the right
    /// edge (plus gap), and cannot catch the current head at the left
    /// edge.
    fn can_fit(&self, stime: i64, speed: f64) -> bool {
        let Some(last_stime) = self.last_stime else {
            return true;
        };
        let cond1 = stime as f64
            >= last_stime as f64 + ((self.last_width + self.min_gap) as f64 / self.last_speed);
        let cond2 = stime as f64
            >= last_stime as f64 + self.last_duration as f64
                - ((self.screen_width - self.min_gap) as f64 / speed);
        cond1 && cond2
    }

    fn push(&mut self, stime: i64, duration_ms: i64, text_width: i32, speed: f64) {
        self.last_stime = Some(stime);
        self.last_duration = duration_ms;
        self.last_width = text_width;
        self.last_speed = speed;
    }
}

/// A fixed (top/bottom) track (Python `StaticTrack`).
struct StaticTrack {
    end_time: i64,
}

impl StaticTrack {
    fn new() -> Self {
        Self { end_time: -1 }
    }

    fn can_fit(&self, stime: i64) -> bool {
        stime >= self.end_time
    }

    fn push(&mut self, end_time: i64) {
        self.end_time = end_time;
    }
}

/// Text measurement replacing Qt `QFontMetrics`.
///
/// ponytail: deterministic em-grid metrics (CJK/fullwidth = 1 em, other
/// glyphs = 0.5 em; height = 1.25 em rounded up + 1) instead of a real
/// rasterizer — Python's own output is host-font-dependent (which is why
/// it never got an ASS golden test). Swap for gpui text metrics when the
/// app shell wires rendering; row counts and collision math are unchanged.
struct TextMetrics {
    pixel_size: i32,
}

impl TextMetrics {
    /// `QFontMetrics::horizontalAdvance` equivalent.
    fn advance(&self, text: &str) -> i32 {
        let mut ems = 0.0f64;
        for c in text.chars() {
            ems += if is_fullwidth(c) { 1.0 } else { 0.5 };
        }
        (ems * self.pixel_size as f64).round() as i32
    }

    /// `QFontMetrics::height` equivalent (ascent + descent + 1 leading).
    fn height(&self) -> i32 {
        (self.pixel_size as f64 * 1.2).ceil() as i32 + 1
    }
}

/// CJK ideographs, fullwidth forms and the common wide ranges occupy one
/// em in 黑体-family fonts.
fn is_fullwidth(c: char) -> bool {
    matches!(c as u32,
        0x1100..=0x115F      // Hangul Jamo
        | 0x2E80..=0x303E    // CJK radicals, Kangxi, CJK symbols
        | 0x3041..=0x33FF    // kana, CJK compatibility
        | 0x3400..=0x4DBF    // CJK ext A
        | 0x4E00..=0x9FFF    // CJK unified
        | 0xA000..=0xA4CF    // Yi
        | 0xAC00..=0xD7A3    // Hangul syllables
        | 0xF900..=0xFAFF    // CJK compatibility ideographs
        | 0xFE30..=0xFE4F    // CJK compatibility forms
        | 0xFF00..=0xFF60    // fullwidth forms
        | 0xFFE0..=0xFFE6
        | 0x20000..=0x2FFFD // CJK ext B..
        | 0x30000..=0x3FFFD
    )
}

/// The layout engine (Python `DanmakuLayoutEngine`).
struct LayoutEngine {
    screen_width: i32,
    screen_height: i32,
    metrics: TextMetrics,
    line_height: i32,
    scroll_tracks: Vec<ScrollTrack>,
    top_tracks: Vec<StaticTrack>,
    bottom_tracks: Vec<StaticTrack>,
}

impl LayoutEngine {
    fn new(style: &DanmakuStyle, screen_width: i32, screen_height: i32) -> Self {
        let metrics = TextMetrics {
            pixel_size: style.font.size,
        };
        let line_height = metrics.height() + 4;
        let display_area = style.advanced.display_area as f64 / 100.0;
        let min_gap = style.advanced.minimum_gap;

        let max_scroll_rows =
            (((screen_height as f64 * display_area) / line_height as f64) as i32).max(1);
        let max_static_rows =
            ((screen_height as f64 * display_area / line_height as f64) as i32).max(1);

        Self {
            screen_width,
            screen_height,
            metrics,
            line_height,
            scroll_tracks: (0..max_scroll_rows)
                .map(|_| ScrollTrack::new(screen_width, min_gap))
                .collect(),
            top_tracks: (0..max_static_rows).map(|_| StaticTrack::new()).collect(),
            bottom_tracks: (0..max_static_rows).map(|_| StaticTrack::new()).collect(),
        }
    }

    fn alloc_scroll(&mut self, stime: i64, text_width: i32, duration_ms: i64) -> Option<usize> {
        let speed = (self.screen_width + text_width) as f64 / duration_ms as f64;
        for (row, track) in self.scroll_tracks.iter_mut().enumerate() {
            if track.can_fit(stime, speed) {
                track.push(stime, duration_ms, text_width, speed);
                return Some(row);
            }
        }
        None
    }

    fn alloc_top(&mut self, stime: i64, duration_ms: i64) -> Option<usize> {
        for (row, track) in self.top_tracks.iter_mut().enumerate() {
            if track.can_fit(stime) {
                track.push(stime + duration_ms);
                return Some(row);
            }
        }
        None
    }

    fn alloc_bottom(&mut self, stime: i64, duration_ms: i64) -> Option<usize> {
        for (row, track) in self.bottom_tracks.iter_mut().enumerate() {
            if track.can_fit(stime) {
                track.push(stime + duration_ms);
                return Some(row);
            }
        }
        None
    }
}

fn convert_dialogues(
    engine: &mut LayoutEngine,
    entries: &[DanmakuEntry],
    style: &DanmakuStyle,
) -> Vec<String> {
    // Sorted by stime (Python `DanmakuASS.__init__`).
    let mut sorted: Vec<&DanmakuEntry> = entries.iter().collect();
    sorted.sort_by_key(|e| e.stime);

    let scroll_ms = style.advanced.scroll_duration * 1000;
    let static_ms = style.advanced.static_duration * 1000;

    let mut dialogues = Vec::new();
    for entry in sorted {
        let stime = entry.stime;
        let text = entry.text.as_str();
        if text.is_empty() {
            continue;
        }
        let (duration_ms, kind) = match entry.mode {
            1..=3 => (scroll_ms, 0), // scroll
            4 => (static_ms, 2),    // bottom
            5 => (static_ms, 1),    // top
            _ => continue,
        };
        let text_width = engine.metrics.advance(text);
        let start = ass_time(stime);
        let end = ass_time(stime + duration_ms);

        let allocated_row = match kind {
            0 => engine.alloc_scroll(stime, text_width, duration_ms).map(|r| {
                let y = r as i32 * engine.line_height;
                format!("\\move({},{y},-{text_width},{y})", engine.screen_width)
            }),
            1 => engine.alloc_top(stime, duration_ms).map(|r| {
                let y = r as i32 * engine.line_height;
                format!("\\an8\\pos({},{y})", engine.screen_width / 2)
            }),
            _ => engine.alloc_bottom(stime, duration_ms).map(|r| {
                let y = engine.screen_height - r as i32 * engine.line_height;
                format!("\\an2\\pos({},{y})", engine.screen_width / 2)
            }),
        };

        let Some(style_label) = allocated_row else {
            // No free track (screen full) — drop to avoid overlap.
            continue;
        };

        let color_tag = if entry.color != 0 && entry.color != 16_777_215 {
            let c = entry.color;
            let bgr = ((c & 0xFF) << 16) | (c & 0xFF00) | ((c >> 16) & 0xFF);
            format!("\\c&H{bgr:06X}&")
        } else {
            String::new()
        };

        dialogues.push(format!(
            "Dialogue: 0,{start},{end},Default,,0,0,0,,{{{style_label}{color_tag}}}{text}"
        ));
    }
    dialogues
}
